# Generated by build.py from recipe.yml for recipe smtp-log-in-with-cram-md5. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'hi.eml'), "From: ann@example.com`nTo: bob@example.com`nSubject: Lunch`n`nNoon at the usual place.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'plain.smtp'), "EHLO client`r`nAUTH PLAIN AGFubkBleGFtcGxlLmNvbQBhbm5wYXNz`r`nAUTH PLAIN AGFubkBleGFtcGxlLmNvbQB3cm9uZw==`r`nAUTH LOGIN`r`nQUIT`r`n")
[IO.File]::WriteAllText((Join-Path $PWD 'decode-login.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Sends hi.eml once with curl -v on the port given, then decodes the two lines of the CRAM-MD5`n# login: the server's challenge and curl's answer to it.`ncurl -v --crlf -u ann@example.com:annpass --mail-from ann@example.com --mail-rcpt bob@example.com \`n  -T hi.eml `"smtp://127.0.0.1:`$1/example.com`" 2>&1 |`n  tr -d '\r' | sed -n -e '/^> AUTH CRAM-MD5`$/{n;s/^< 334 //p;n;s/^> //p;}' |`n  while read -r line; do printf '%s' `"`$line`" | base64 -d; echo; done`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'bob@example.com:bobpass', 'smtp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --crlf -u ann@example.com:annpass --mail-from ann@example.com --mail-rcpt bob@example.com -T hi.eml -w "%{response_code}\n" smtp://127.0.0.1:8080/example.com } finally { Stop-Process $server0 }
